  [433427] = { "Proteggiti dagli elementi finché sopravvivi.", "Senti un tepore piacevole dentro di te.", 0x0590d635, 0xa188eb32, "uu" },
  [433521] = { "Migliora in vari modi i tuoi veleni:\n\nQuando applichi un qualsiasi altro veleno a un bersaglio, applichi anche ⟦Deadly Poison=Veleno Mortale⟧.\n\nSe sulla tua arma non è applicato alcun veleno, essa ha una probabilità di attivare ⟦Instant Poison=Veleno Istantaneo⟧ come se ⟦Instant Poison=Veleno Istantaneo⟧ fosse applicato.\n\n⟦Deadly Poison=Veleno Mortale⟧ e ⟦Instant Poison=Veleno Istantaneo⟧ ora ottengono più danni dalla tua potenza d'attacco.", nil, 0x12ceea9e, nil, "um" },
  [433546] = { "L'incantatore scaglia un'ondata di melma tossica su tutti i giocatori, infliggendo $N1 danni da natura e altri $N2 danni da natura ogni $D1 per $D2. Questo effetto è cumulabile.", "$N1 danni da natura inflitti ogni $D1.", 0xdae18fd3, 0xd8c7b0a1, "uu" },
